 {"id": "PEDS-C31-116", "sec": "PDA management", "page": 140, "q": "Surgery is indicated in preterm PDA when —", "opts": ["Not responding to medical management or medical Rx is contraindicated", "The murmur is soft and the baby is thriving well", "The baby has completed one year of age", "The ECG shows a normal sinus rhythm"], "ans": 0, "exp": "Preterm baby: not responding to medical mx OR C/I to medical mx (Book p140)", "type": "mcq"},
