 {"id": "PEDS-C31-118", "sec": "PDA management", "page": 140, "q": "A contraindication to medical PDA closure is serum creatinine greater than ___ mg/dl.", "opts": ["0.5", "2.5", "1.8", "1.0"], "ans": 2, "exp": "Serum creatinine >1.8 mg/dl (Book p140)", "type": "fill"},
 {"id": "PEDS-C31-119", "sec": "PDA management", "page": 140, "q": "Any ___ bleeding is a contraindication to medical PDA closure.", "opts": ["resolved", "mild", "remote", "active"], "ans": 3, "exp": "Any active bleeding (Book p140)", "type": "fill"},
 {"id": "PEDS-C31-120", "sec": "PDA management", "page": 140, "q": "Surgery is indicated in which of the following PDA patients?", "opts": ["All term babies", "Preterm with small PDA responding to NSAIDs", "Term infant with closed duct", "Any asymptomatic child"], "ans": 0, "exp": "Surgical indication: 2. all term babies (Book p140)", "type": "mcq"},
 {"id": "PEDS-C31-121", "sec": "PDA management", "page": 140, "q": "A surgical technique for PDA is —", "opts": ["Stenting", "Ligation", "Balloon dilatation", "Dacron patch closure"], "ans": 1, "exp": "Technique: 1. ligation (Book p140)", "type": "mcq"},
 {"id": "PEDS-C31-122", "sec": "PDA management", "page": 140, "q": "Percutaneous catheterization for PDA closure uses —", "opts": ["Dacron patches", "Stents only", "Occluders or coils", "Balloon only"], "ans": 2, "exp": "Percutaneous catheterization using occluders or coils (Book p140)", "type": "mcq"},
