 {"id": "PEDS-C31-124", "sec": "PDA management", "page": 140, "stem": "A term infant with a hemodynamically significant PDA is otherwise well.", "q": "The definitive management per the book is —", "opts": ["Surgery (ligation or percutaneous device)", "Long-term NSAID therapy with monitoring", "Observation until symptoms develop", "Antibiotics and supportive care"], "ans": 0, "exp": "All term babies: surgical — ligation / percutaneous catheterization (Book p140)", "type": "case"},
 {"id": "PEDS-C31-125", "sec": "Coarctation", "page": 140, "q": "The most common location of coarctation of the aorta is ___.", "opts": ["abdominal", "juxta-ductal (near the ductus arteriosus)", "ascending", "arch distal to the left subclavian only"], "ans": 1, "exp": "m/c location: juxta-ductal (near ductus arteriosus) (Book p140)", "type": "fill"},
 {"id": "PEDS-C31-126", "sec": "Coarctation", "page": 140, "q": "Coarctation is the obstructive lesion under acyanotic CHD.", "opts": ["True", "False"], "ans": 0, "exp": "True — obstructive lesions: coarctation of aorta (Book p140)", "type": "tf"},
 {"id": "PEDS-C31-127", "sec": "Coarctation", "page": 140, "q": "Near-complete coarctation is —", "opts": ["The most common type", "The mildest type", "Self-limiting", "Uncommon"], "ans": 3, "exp": "Near complete (uncommon) (Book p140)", "type": "mcq"},
 {"id": "PEDS-C31-128", "sec": "Coarctation", "page": 140, "q": "Near-complete coarctation with severely restricted blood flow presents as —", "opts": ["Shock in neonates", "Mild hypertension", "Asymptomatic state", "Recurrent pneumonia"], "ans": 0, "exp": "Near complete → severely restricted blood flow → shock in neonates (Book p140)", "type": "mcq"},
