 {"id": "PEDS-C31-130", "sec": "Coarctation", "page": 140, "q": "Reduced blood flow to the lower limbs in coarctation causes —", "opts": ["Hyperhidrosis", "Paresthesia only", "Claudication pain", "Painless warm limbs"], "ans": 2, "exp": "↓ BF to lower limbs: claudication pain (Book p140)", "type": "mcq"},
 {"id": "PEDS-C31-131", "sec": "Coarctation", "page": 140, "q": "Lower limb signs in coarctation include —", "opts": ["Bounding femoral pulses with early closure", "Increased femoral pulses with claudication", "Normal femoral pulses with warm calves", "Feeble femoral pulses and radio-femoral delay"], "ans": 3, "exp": "Feeble femoral pulses, radio-femoral delay (Book p140)", "type": "mcq"},
 {"id": "PEDS-C31-132", "sec": "Coarctation", "page": 140, "q": "Renal ischemia in coarctation leads to —", "opts": ["Renin release", "Renal atrophy", "Diabetes insipidus", "Acalculous cholecystitis"], "ans": 0, "exp": "↓ BF to kidneys (ischemia) → renin release (Book p140)", "type": "mcq"},
 {"id": "PEDS-C31-133", "sec": "Coarctation", "page": 140, "q": "RAAS activation in coarctation increases —", "opts": ["Thyroxine", "Aldosterone", "Insulin", "Cortisol only"], "ans": 1, "exp": "Activation of RAAS: ↑ aldosterone (renin angiotensin aldosterone system) → hypertension++ (Book p140)", "type": "mcq"},
 {"id": "PEDS-C31-134", "sec": "Coarctation", "page": 140, "q": "RAAS stands for renin-___-aldosterone system.", "opts": ["glucagon", "aldosterone", "angiotensin", "cortisol"], "ans": 2, "exp": "Renin angiotensin aldosterone system (Book p140)", "type": "fill"},
 {"id": "PEDS-C31-135", "sec": "Coarctation", "page": 140, "q": "Systemic hypertension in partial coarctation is due to —", "opts": ["Decreased resistance", "Renal artery stenosis", "Aortic regurgitation", "Increased resistance"], "ans": 3, "exp": "Systemic hypertension d/t ↑ resistance (Book p140)", "type": "mcq"},
 {"id": "PEDS-C31-136", "sec": "Coarctation", "page": 140, "q": "Hypertension in coarctation can cause hypertensive encephalopathy, which presents with —", "opts": ["Seizures", "Hemiplegia", "Aphasia", "Coma only"], "ans": 0, "exp": "Hypertension → hypertensive encephalopathy → presents with seizures (Book p140)", "type": "mcq"},
 {"id": "PEDS-C31-137", "sec": "Coarctation", "page": 140, "q": "Match the coarctation feature — select the correct combination:", "pairs": [["Near complete", "claudication + feeble femorals"], ["Partial narrowing (m/c)", "↑ aldosterone→HTN"], ["Renal ischemia", "shock in neonates"], ["RAAS activation", "renin→RAAS"]], "opts": ["A-2, B-1, C-4, D-3", "A-2, B-1, C-3, D-4", "A-3, B-1, C-4, D-2", "A-3, B-4, C-2, D-1"], "ans": 2, "exp": "Correct pairs: Near complete→shock in neonates; Partial narrowing (m/c)→claudication + feeble femorals; Renal ischemia→renin→RAAS; RAAS activation→↑ aldosterone→HTN. (Book p140)", "type": "match"},
 {"id": "PEDS-C31-138", "sec": "Coarctation", "page": 140, "q": "Odd one out (lower-limb signs in coarctation):", "opts": ["Feeble femoral pulses", "Radio-femoral delay", "Bounding brachial pulses", "Claudication pain"], "ans": 2, "exp": "The first three are lower-limb signs of coarctation; the brachial (upper limb) pulses are NOT feeble — upper limb pressure is high. (Book p140)", "type": "odd"},
 {"id": "PEDS-C31-139", "sec": "Coarctation", "page": 140, "stem": "A 2-year-old has blood pressure of 140/90 mmHg in the arms, weak femoral pulses and a radio-femoral delay.", "q": "The most likely diagnosis is —", "opts": ["Patent ductus arteriosus", "Ventricular septal defect", "Hypertensive encephalopathy", "Coarctation of the aorta"], "ans": 3, "exp": "Upper limb hypertension + feeble femorals + radio-femoral delay = coarctation (Book p140)", "type": "case"},
 {"id": "PEDS-C31-140", "sec": "Coarctation — compensation", "page": 141, "q": "Compensatory changes in coarctation are noted in older children of age —", "opts": [">10 years", "<1 year", "5–10 years", ">15 years"], "ans": 0, "exp": "Noted in older children (>10y) (Book p141)", "type": "mcq"},
 {"id": "PEDS-C31-141", "sec": "Coarctation — compensation", "page": 141, "q": "In compensatory changes, blood is diverted to the ___ arteries.", "opts": ["mesenteric", "intercostal", "coronary", "renal"], "ans": 1, "exp": "Blood diverted to intercostal (IC) arteries (Book p141)", "type": "fill"},
 {"id": "PEDS-C31-142", "sec": "Coarctation — compensation", "page": 141, "q": "The intercostal arteries in coarctation become —", "opts": ["Calcified", "Thrombosed", "Dilated and tortuous", "Narrowed and straight"], "ans": 2, "exp": "↑ size of IC artery (dilated and tortuous) (Book p141)", "type": "mcq"},
 {"id": "PEDS-C31-143", "sec": "Coarctation — compensation", "page": 141, "q": "The dilated intercostal arteries press on the ___ border of the rib.", "opts": ["upper", "lateral", "medial", "lower"], "ans": 3, "exp": "Pressure on lower border of rib (Book p141)", "type": "fill"},
 {"id": "PEDS-C31-144", "sec": "Coarctation — compensation", "page": 141, "q": "The X-ray sign produced by collateral pressure on the ribs is —", "opts": ["Inferior rib notching", "Superior rib notching", "Rib fraying", "Ridging of the clavicle"], "ans": 0, "exp": "Inferior rib notching (Book p141)", "type": "mcq"},
