 {"id": "PEDS-C31-146", "sec": "Coarctation — compensation", "page": 141, "q": "Match the compensatory step — select the correct combination:", "pairs": [["Collaterals", "inferior rib notching"], ["Dilated IC arteries", "pre + post-stenotic dilatation"], ["X-ray finding", "blood to IC arteries"], ["3-sign", "pressure on lower rib border"]], "opts": ["A-3, B-2, C-1, D-4", "A-3, B-4, C-1, D-2", "A-2, B-3, C-1, D-4", "A-2, B-4, C-1, D-3"], "ans": 1, "exp": "Correct pairs: Collaterals→blood to IC arteries; Dilated IC arteries→pressure on lower rib border; X-ray finding→inferior rib notching; 3-sign→pre + post-stenotic dilatation. (Book p141)", "type": "match"},
 {"id": "PEDS-C31-147", "sec": "Coarctation — compensation", "page": 141, "q": "Treatment of coarctation of the aorta is —", "opts": ["Digoxin and furosemide", "NSAIDs", "Dacron patch closure", "Balloon dilatation ± stenting"], "ans": 3, "exp": "Treatment: balloon dilatation of coarctation ± stenting (Book p141)", "type": "mcq"},
 {"id": "PEDS-C31-148", "sec": "Coarctation — compensation", "page": 141, "stem": "A 12-year-old with long-standing hypertension has notching of the lower rib margins on chest X-ray.", "q": "This sign results from —", "opts": ["Dilated tortuous intercostal collaterals pressing on the lower rib border", "Repetitive rib stress fractures from coughing", "Progressive scoliosis with thoracic kyphosis and rib flare", "Pleural thickening from recurrent infection"], "ans": 0, "exp": "Dilated & tortuous IC arteries → pressure on lower border of rib → inferior rib notching (Book p141)", "type": "case"},
